import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    conditions := glitch_lib.all_conditional_statements(parent)
    cs := conditions[_]
    cs.is_top == true

    # Collect all conditions in the chain (if -> else if -> else)
    all_conditions := collect_conditions(cs)

    # Check if any of them is a default case
    has_default := false
    some c in all_conditions
    c.is_default == true

    # If no default is found, report the issue
    not has_default

    result := {
        "type": "sec_no_default_switch",
        "element": cs,
        "path": parent.path,
        "description": "Missing default case in multiple condition expression - This may lead to undefined behavior when an unexpected condition is encountered. (CWE-478)"
    }
}

# Helper function to collect all conditions in the chain
collect_conditions(cs) := set {
    current := cs
    conditions := {current}
    while current.else_statement != null {
        current := current.else_statement
        conditions := conditions | {current}
    }
    set := conditions
}

